using System.Reflection;
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
    [DataRow(100.00, 2, 1.0, 400.00, DisplayName = "Maximum tax rate (100%)")]
    public void CalculateTotal_ValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result);
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, "unitPrice", DisplayName = "Negative unit price throws")]
    [DataRow(10.00, -1, 0.10, "quantity", DisplayName = "Negative quantity throws")]
    [DataRow(10.00, 1, -0.01, "taxRate", DisplayName = "Negative tax rate throws")]
    [DataRow(10.00, 1, 1.01, "taxRate", DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidInputs_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate, string expectedParamName)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));

        Assert.AreEqual(expectedParamName, ex.ParamName);
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> ApplyDiscountValidCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m };   // No discount
            yield return new object[] { 100.00m, 10m, 90.00m };   // 10% off
            yield return new object[] { 100.00m, 50m, 50.00m };   // Half off
            yield return new object[] { 100.00m, 100m, 0.00m };   // Free
            yield return new object[] { 49.99m, 25m, 37.4925m };  // Fractional result
            yield return new object[] { 0.00m, 50m, 0.00m };      // Zero price
            yield return new object[] { 200.00m, 33.33m, 133.34m }; // Repeating decimal discount
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountValidCases))]
    public void ApplyDiscount_ValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result);
    }

    public static IEnumerable<object[]> ApplyDiscountInvalidCases
    {
        get
        {
            yield return new object[] { 100.00m, -1m };    // Below zero
            yield return new object[] { 100.00m, 100.01m }; // Above 100
            yield return new object[] { 50.00m, -50m };    // Large negative
            yield return new object[] { 50.00m, 200m };    // Way above 100
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountInvalidCases))]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        decimal price, decimal discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    // --- DynamicData from a method (alternative pattern) ---

    public static IEnumerable<object[]> GetCalculateTotalBoundaryData()
    {
        yield return new object[] { decimal.MaxValue / 2, 1, 0.0m, decimal.MaxValue / 2 };
        yield return new object[] { 0.01m, 1, 0.0m, 0.01m };
        yield return new object[] { 0.01m, 1, 1.0m, 0.02m };
    }

    [TestMethod]
    [DynamicData(nameof(GetCalculateTotalBoundaryData), DynamicDataSourceType.Method)]
    public void CalculateTotal_BoundaryValues_ReturnsExpectedTotal(
        decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expectedTotal, result);
    }
}

